'use strict';
let companyProfile=null,companyPage=1,companySequence=0;
const companyDrafts=new Map();
function researchAmount(amount){if(amount==null)return "UNKNOWN";if(typeof amount!=="object")return String(amount);return Number(amount.value).toLocaleString("en-US")+" "+(amount.currency||"CURRENCY UNKNOWN");}
const usd=v=>v==null?'UNKNOWN':(v<0?'−':'')+'$'+(Math.abs(v)>=1e9?(Math.abs(v)/1e9).toFixed(2)+'B':Math.abs(v)>=1e6?(Math.abs(v)/1e6).toFixed(1)+'M':Math.abs(v).toLocaleString('en-US'));
function pulseHtml(pulse){if(!pulse?.available)return `<h4>FEDERAL CONTRACT OBLIGATIONS</h4><p>${esc(pulse?.reason||'Pulse unavailable')}</p>`;const x=pulse.parent;if(!x)return `<h4>FEDERAL CONTRACT OBLIGATIONS</h4><p>No reviewed UEI bindings resolve to this issuer; company-wide obligations UNKNOWN.</p>`;
 const max=Math.max(1,...x.series.map(s=>Math.abs(s.obligations||0)));const change=x.changePercent==null?'UNKNOWN':(x.changePercent>0?'+':'')+x.changePercent.toFixed(1)+'%';
 const bars=x.series.map(s=>{const h=s.obligations==null?0:Math.round(Math.abs(s.obligations)/max*100);return `<div title="${esc(s.month)}: ${esc(usd(s.obligations))}${s.settled?'':' (provisional)'}${s.continuation?' · continuation basis':''} · ${s.activeUeis}/${s.boundUeis} UEIs active" style="flex:1;display:flex;align-items:flex-end;height:90px;opacity:${s.settled?1:.4}"><div style="width:100%;height:${h}%;background:${s.obligations<0?'#ff8a7a':'var(--bright)'}"></div></div>`;}).join('');
 return `<h4>FEDERAL CONTRACT OBLIGATIONS / ${esc(x.boundUeis)} REVIEWED UEIs</h4><p>Trailing 12 settled months (${esc(x.trailing12.window?.join(' – ')||'n/a')}): <span class="bright">${esc(usd(x.trailing12.obligations))}</span> · prior 12: ${esc(usd(x.prior12.obligations))} · change ${esc(change)} · ${x.revenueSharePercent==null?'revenue share UNKNOWN':`${esc(x.revenueSharePercent.toFixed(1))}% of fiscal ${esc(x.revenue.fiscalYearEnd)} revenue (${esc(usd(x.revenue.value))})`}${x.usesContinuation?' · includes government-record continuation months':''}</p>
 <div style="display:flex;gap:2px;border-bottom:1px solid var(--line);margin:8px 0 2px" aria-label="Monthly obligations bar chart">${bars}</div><p class="eyebrow">${esc(x.series[0].month)} → ${esc(x.series.at(-1).month)} · faded bars are provisional (DoD ${esc(pulse.settleDays)}-day reporting delay) · red = net deobligation · retrieved ${esc(pulse.retrievedAt.slice(0,10))}</p>
 ${x.missing.length?`<p>Limits: ${esc(x.missing.join('; '))}</p>`:''}<details><summary>PULSE CAVEATS</summary>${pulse.caveats.map(c=>`<p>${esc(c)}</p>`).join('')}</details>`;}
async function loadPulseOverview(){try{const response=await fetch('/api/pulse');const p=await response.json();if(!response.ok)throw new Error(p.error||'Pulse unavailable');
 const pct=v=>v==null?'UNKNOWN':(v>0?'+':'')+v.toFixed(1)+'%';
 $('pulseOverview').innerHTML=`<p class="eyebrow">Trailing 12 settled months of federal contract obligations on reviewed UEIs, vs the prior 12. Retrieved ${esc(p.retrievedAt.slice(0,10))}. Lower bound; obligations are not revenue.</p><div class="table-wrap"><table><thead><tr><th>Public parent</th><th>UEIs</th><th>Trailing 12</th><th>Prior 12</th><th>Change</th><th>% of revenue</th></tr></thead><tbody>${p.parents.map(x=>`<tr><td>${esc(x.parent)}${x.usesContinuation?' *':''}</td><td>${esc(x.boundUeis)}</td><td>${esc(usd(x.trailing12.obligations))}</td><td>${esc(usd(x.prior12.obligations))}</td><td>${esc(pct(x.changePercent))}</td><td>${esc(x.revenueSharePercent==null?'UNKNOWN':x.revenueSharePercent.toFixed(1)+'%')}</td></tr>`).join('')}</tbody></table></div><p class="eyebrow">* includes months resolved through government-record continuation. ${p.excluded.length} bound UEIs had activity outside reviewed ownership windows (excluded).</p>`;}
 catch(e){$('pulseOverview').innerHTML=`<p>${esc(e.message)}</p>`;}}
async function loadResearchCompanies(){try{const response=await fetch('/api/research/companies');if(!response.ok)throw new Error('Company research unavailable');const data=await response.json();$('researchCompany').innerHTML=data.companies.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}${data.research.watches.some(w=>w.company===c.name)?' / WATCHED':''}</option>`).join('');await loadCompanyProfile();}catch(e){$('researchStatus').textContent=e.message;}}
async function loadCompanyProfile(){const sequence=++companySequence;try{const response=await fetch('/api/research/profile?'+new URLSearchParams({company:$('researchCompany').value,page:String(companyPage)}));if(!response.ok)throw new Error('Company profile unavailable');const profile=await response.json();if(sequence!==companySequence)return;companyProfile=profile;const watched=profile.research.watches.some(w=>w.company===profile.company.name);$('watchResearchCompany').textContent=watched?'UNWATCH COMPANY':'WATCH COMPANY';$('researchStatus').textContent=`${profile.company.name} / ${watched?'WATCHED LOCALLY':'NOT WATCHED'} / ${profile.timeline.pagination.total} observed source events`;const issuer=profile.issuer;$('researchProfile').innerHTML=`<h3>${esc(profile.company.name)}</h3><p>${esc(profile.identityScope)}</p><p>Issuer directory: ${esc(issuer?.legalName||'UNRESOLVED')} · Ticker ${esc(issuer?.ticker||'UNRESOLVED')} · CIK ${esc(issuer?.cik||'UNKNOWN')}. Issuer evidence does not verify the award recipient.</p>${pulseHtml(profile.pulse)}<h4>DATED CORPORATE RELATIONSHIPS</h4>${profile.relationships.length?profile.relationships.map(r=>`<p>${esc(r.child.legalName)} → ${esc(r.parent.legalName)} / evidence as of ${esc(r.evidenceAsOf)}. Recipient identifiers: see reviewed UEI bindings.<br>${r.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.section)}</a>`).join(' · ')}</p>`).join(''):'<p>No reviewed relationship evidence linked to this issuer.</p>'}<details><summary>SOURCE COVERAGE / ${profile.sources.length} configured sources</summary>${profile.sources.map(s=>`<p>${esc(s.name)} / ${esc(s.state)} / successful check ${esc(s.lastSuccess||'NEVER')}<br>${esc(s.coverage)}</p>`).join('')}</details><button id="companyContractAlert">ALERT ON CONTRACT MENTIONS</button><p>Watching saves this research name. Alerts require a saved rule and a running collector.</p>`;$('companyContractAlert').onclick=async()=>{try{await companyAction('/api/intelligence/rules',{company:profile.company.name,cue:'contract'});$('researchStatus').textContent='Contract-mention alert rule saved. Matches remain research leads.';}catch(e){$('researchStatus').textContent=e.message;}};
$('companyTimeline').innerHTML=profile.timeline.events.length?profile.timeline.events.map(e=>`<article class="evidence"><h3>${esc(e.linkedDocuments[0].title)}</h3><p>${esc(e.procurementStage.toUpperCase())} / PROVISIONAL · Observed ${esc(e.firstObservedAt)}</p><p>Published: ${esc(e.sourcePublishedAt||'UNKNOWN')} (${esc(e.sourcePublicationPrecision)}) · Public parent for recipient: ${esc(e.verifiedPublicParent||'UNRESOLVED')}</p><p>Announced amount: ${esc(researchAmount(e.financial.headlineAmount))} · Newly obligated: ${esc(e.financial.newlyObligatedAmount??'UNKNOWN')} · Allocation: ${esc(e.financial.companyAllocation??'UNKNOWN')}</p><p><a href="${esc(e.linkedDocuments[0].url)}" target="_blank" rel="noopener">OPEN ORIGINAL SOURCE</a></p><label><input type="checkbox" data-note-evidence="${esc(e.sourceIdentifiers.evidenceId)}"> Attach this evidence to the next note</label><button data-company-document="${esc(e.sourceIdentifiers.evidenceId)}">INSPECT SAVED DOCUMENT</button><div id="company-doc-${esc(e.sourceIdentifiers.evidenceId)}"></div></article>`).join(''):'<p>No matching observed source events. Coverage is incomplete; this does not prove absence of activity.</p>';$('companyPrevious').disabled=companyPage<=1;$('companyNext').disabled=companyPage>=profile.timeline.pagination.pages;$('companyTimeline').querySelectorAll('[data-company-document]').forEach(b=>b.onclick=()=>inspectCompanyDocument(b.dataset.companyDocument));$('researchNotes').innerHTML=profile.research.notes.filter(n=>n.company===profile.company.name).reverse().map(n=>`<article class="evidence"><p>${esc(n.createdAt)} / PRIVATE LOCAL NOTE</p><p style="white-space:pre-wrap">${esc(n.text)}</p>${(n.references||[]).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a>`).join('<br>')}</article>`).join('')||'<p>No notes saved for this research name.</p>'; }catch(e){$('researchStatus').textContent=e.message;}}
async function companyAction(url,input){const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Sentinel-Action':'scan'},body:JSON.stringify(input)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Research action failed');return data;}
async function inspectCompanyDocument(id){const target=$('company-doc-'+id);target.textContent='Loading saved evidence…';try{const response=await fetch('/api/documents?id='+encodeURIComponent(id));if(!response.ok)throw new Error('Saved document unavailable');const record=await response.json();if(!record?.versions?.length){target.textContent='No document snapshot saved. Retrieve the underlying document from Source Intelligence; headline evidence remains unverified.';return;}const version=record.versions.at(-1);target.innerHTML=`<details open class="event-details"><summary>SAVED HTML / ${esc(version.reviewStatus)}</summary><p>Retrieved ${esc(version.retrievedAt)} · Hash ${esc(version.hash)}. This is a saved snapshot, not a fresh source check.</p>${version.passages.filter(p=>p.researchCue).slice(0,20).map(p=>`<p><b>${esc(p.id)}</b> ${esc(p.text)}</p>`).join('')}</details>`;}catch(e){target.textContent=e.message;}}
$('researchNote').oninput=()=>companyDrafts.set($('researchCompany').value,$('researchNote').value);$('researchCompany').onchange=()=>{$('researchNote').value=companyDrafts.get($('researchCompany').value)||'';companyProfile=null;companyPage=1;loadCompanyProfile()};$('watchResearchCompany').onclick=async()=>{if(!companyProfile)return;try{const name=companyProfile.company.name,enabled=!companyProfile.research.watches.some(w=>w.company===name);await companyAction('/api/research/watch',{company:name,enabled});await loadCompanyProfile();}catch(e){$('researchStatus').textContent=e.message;}};$('researchNoteForm').onsubmit=async e=>{e.preventDefault();if(!companyProfile)return;try{const evidenceIds=Array.from(document.querySelectorAll('[data-note-evidence]:checked')).map(b=>b.dataset.noteEvidence);await companyAction('/api/research/note',{company:companyProfile.company.name,text:$('researchNote').value,evidenceIds});companyDrafts.delete(companyProfile.company.name);$('researchNote').value='';await loadCompanyProfile();$('researchStatus').textContent='Private local note saved with source references.';}catch(error){$('researchStatus').textContent=error.message;}};$('companyPrevious').onclick=()=>{companyPage--;loadCompanyProfile()};$('companyNext').onclick=()=>{companyPage++;loadCompanyProfile()};document.querySelector('[data-view="companies"]').addEventListener('click',loadCompanyProfile);loadPulseOverview();loadResearchCompanies();
